// Snapshot of the existing Africa Apps Store hosted-card renderer, 2026-10-27.
async function hostedCards(){
 const apps=await api('/hosted-apps'),q=$('#query').value.toLowerCase();
 $('#content').innerHTML=apps.filter(a=>(a.name+' '+a.description+' '+a.domain).toLowerCase().includes(q)).map(a=>`<article>${a.domain==='kakakin.africandroid.world'?'<img src="/downloads/kakakin-logo.png" alt="Kakakin" width="120" height="120">':''}${a.domain==='cellblockcatandmouse.africandroid.world'?'<img src="/downloads/cellblock-logo.webp" alt="Cellblock Cat and Mouse" width="120" height="120">':''}${a.domain==='postmaster.justisolve.com'?'<img src="/downloads/postmaster-logo.png" alt="Postmaster" width="120">':''}${a.domain==='identity.africandroid.world'?'<img src="/downloads/aims-logo.png" alt="AIMS" width="120" height="120">':''}${a.domain==='justisolve.com'?'<img src="/downloads/justisolve-icon.png" alt="JustiSolve" width="120" height="120">':''}${a.domain==='media.africandroid.world'?'<img src="/static/africa-media-icon.svg" alt="Africa Media Hub" width="120" height="120">':''}${a.domain==='afribulkhub.com'?'<img src="/downloads/africa-bulk-hub-logo.png" alt="Africa Bulk Hub" width="220">':''}${a.domain==='jobs.africandroid.world'?'<img src="/downloads/africa-jobs-logo.png" alt="Africa Jobs" width="220">':''}${a.domain==='epafestival.africandroid.world'?'<img src="https://epafestival.africandroid.world/assets/app-192.png" alt="Epa: Spirit of Oro-Ago" width="120" height="120">':''}<h3>${esc(a.name)}</h3><p>${esc(a.domain)}</p><p>${esc(a.description)}</p><ul>${a.features.map(f=>`<li>${esc(f)}</li>`).join('')}</ul><p>${esc(a.limitations)}</p><p>${['kakakin.africandroid.world','cellblockcatandmouse.africandroid.world','media.africandroid.world','justisolve.com','sip.dobhrap.com','academy.africandroid.world','epafestival.africandroid.world'].includes(a.domain)?esc(a.platforms):'Android 8+ · '+(['afribulkhub.com','identity.africandroid.world'].includes(a.domain)?'Direct APK':'Development edition')}</p>${a.apk_url?`<a class="button" href="${esc(a.apk_url)}">Download APK</a><p><small>SHA-256: ${esc(a.sha256)}</small></p>`:a.domain==='sip.dobhrap.com'?'<a class="button" href="/install/sip">Install / update for your device</a>':a.domain==='media.africandroid.world'?'<a class="button" href="https://media.africandroid.world/install" target="_blank" rel="noopener noreferrer">Install / Download for your device</a>':a.install_url?'<p>Installable web app — no APK required</p>':'<p>APK build pending</p>'}${a.domain==='vitabridge.olamidemedical.health'?'<a class="button" href="https://vitabridge.olamidemedical.health/install.html" target="_blank" rel="noopener">Install VitaBridge for your device</a>':''}${a.domain==='justisolve.com'?'<a class="button" href="https://justisolve.com/install" target="_blank" rel="noopener noreferrer">Install on Android / iPhone</a>':''}${a.install_url&&a.install_url.startsWith('https://')?`<a class="button" href="${esc(a.install_url)}" target="_blank" rel="noopener noreferrer">Install on your device</a>`:''}<a href="${esc(a.website)}" target="_blank" rel="noopener">Open website</a></article>`).join('')||'<p>No hosted apps match this search.</p>';
}
